/// Configuration for an episodic Monte Carlo run on the shared 4×4 world.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct MonteCarloConfig {
    pub mode: MonteCarloMode,
    pub visit_strategy: MonteCarloVisitStrategy,
    pub objective: MonteCarloObjective,
    pub discount: f64,
    pub slip_probability: f64,
    pub epsilon: f64,
    pub episodes_per_step: u32,
    pub max_episodes: u32,
    pub max_steps: u32,
    pub seed: u64,
    pub rewards: Rewards,
}

impl Default for MonteCarloConfig {
    fn default() -> Self {
        Self {
            mode: MonteCarloMode::Basic,
            visit_strategy: MonteCarloVisitStrategy::Initial,
            objective: MonteCarloObjective::Control,
            discount: 0.9,
            slip_probability: 0.0,
            epsilon: 0.2,
            episodes_per_step: 1,
            max_episodes: 500,
            max_steps: MAX_MONTE_CARLO_STEPS,
            seed: SHARED_GRID_SEED,
            rewards: Rewards::default(),
        }
    }
}

impl MonteCarloConfig {
    pub fn validate(&self) -> Result<(), MonteCarloConfigError> {
        if !self.discount.is_finite() || !(0.0..=1.0).contains(&self.discount) {
            return Err(MonteCarloConfigError::Discount);
        }
        if !self.slip_probability.is_finite() || !(0.0..=1.0).contains(&self.slip_probability) {
            return Err(MonteCarloConfigError::SlipProbability);
        }
        if !self.epsilon.is_finite() || !(0.0..=1.0).contains(&self.epsilon) {
            return Err(MonteCarloConfigError::Epsilon);
        }
        if !(1..=MAX_MONTE_CARLO_EPISODES_PER_ADVANCE).contains(&self.episodes_per_step) {
            return Err(MonteCarloConfigError::EpisodesPerStep);
        }
        if !(1..=MAX_MONTE_CARLO_EPISODES).contains(&self.max_episodes) {
            return Err(MonteCarloConfigError::MaxEpisodes);
        }
        if !(1..=MAX_MONTE_CARLO_STEPS).contains(&self.max_steps) {
            return Err(MonteCarloConfigError::MaxSteps);
        }
        if [
            self.rewards.default,
            self.rewards.boundary,
            self.rewards.hazard,
            self.rewards.goal,
        ]
        .iter()
        .any(|reward| !reward.is_finite() || reward.abs() > MAX_MONTE_CARLO_REWARD_MAGNITUDE)
        {
            return Err(MonteCarloConfigError::Reward);
        }
        shared_world(*self)
            .validate()
            .map_err(MonteCarloConfigError::World)
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum MonteCarloConfigError {
    Discount,
    SlipProbability,
    Epsilon,
    EpisodesPerStep,
    MaxEpisodes,
    MaxSteps,
    Reward,
    World(ConfigError),
}

impl MonteCarloConfigError {
    pub const fn code(&self) -> &'static str {
        match self {
            Self::Discount => "monte_carlo_discount_range",
            Self::SlipProbability => "monte_carlo_slip_range",
            Self::Epsilon => "monte_carlo_epsilon_range",
            Self::EpisodesPerStep => "monte_carlo_episodes_per_step_range",
            Self::MaxEpisodes => "monte_carlo_max_episodes_range",
            Self::MaxSteps => "monte_carlo_max_steps_range",
            Self::Reward => "monte_carlo_reward_range",
            Self::World(error) => error.code(),
        }
    }
}

impl fmt::Display for MonteCarloConfigError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Discount => write!(formatter, "discount must be finite and in [0, 1]"),
            Self::SlipProbability => {
                write!(formatter, "slip_probability must be finite and in [0, 1]")
            }
            Self::Epsilon => write!(formatter, "epsilon must be finite and in [0, 1]"),
            Self::EpisodesPerStep => write!(
                formatter,
                "episodes_per_step must be between 1 and {MAX_MONTE_CARLO_EPISODES_PER_ADVANCE}"
            ),
            Self::MaxEpisodes => write!(
                formatter,
                "max_episodes must be between 1 and {MAX_MONTE_CARLO_EPISODES}"
            ),
            Self::MaxSteps => write!(
                formatter,
                "max_steps must be between 1 and {MAX_MONTE_CARLO_STEPS}"
            ),
            Self::Reward => write!(
                formatter,
                "rewards must be finite with magnitude at most {MAX_MONTE_CARLO_REWARD_MAGNITUDE}"
            ),
            Self::World(error) => error.fmt(formatter),
        }
    }
}

impl std::error::Error for MonteCarloConfigError {}

#[derive(Debug, Clone, PartialEq)]
pub enum MonteCarloError {
    Config(MonteCarloConfigError),
    EpisodeUnavailable,
    EpisodeGeneration(String),
}

impl MonteCarloError {
    pub const fn code(&self) -> &'static str {
        match self {
            Self::Config(error) => error.code(),
            Self::EpisodeUnavailable => "monte_carlo_episode_unavailable",
            Self::EpisodeGeneration(_) => "monte_carlo_episode_generation",
        }
    }
}

impl fmt::Display for MonteCarloError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Config(error) => error.fmt(formatter),
            Self::EpisodeUnavailable => {
                write!(formatter, "the configured episode budget is exhausted")
            }
            Self::EpisodeGeneration(error) => {
                write!(formatter, "could not generate episode: {error}")
            }
        }
    }
}

impl std::error::Error for MonteCarloError {}

impl From<MonteCarloConfigError> for MonteCarloError {
    fn from(error: MonteCarloConfigError) -> Self {
        Self::Config(error)
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
struct RunningStats {
    count: u32,
    sum: f64,
    mean: f64,
    m2: f64,
    min: f64,
    max: f64,
}

impl RunningStats {
    const fn new() -> Self {
        Self {
            count: 0,
            sum: 0.0,
            mean: 0.0,
            m2: 0.0,
            min: f64::INFINITY,
            max: f64::NEG_INFINITY,
        }
    }

    fn update(&mut self, value: f64) {
        if !value.is_finite() {
            return;
        }
        let next_count = self.count.saturating_add(1);
        if next_count == 0 {
            return;
        }
        self.count = next_count;
        self.sum += value;
        let delta = value - self.mean;
        self.mean += delta / self.count as f64;
        let delta_after = value - self.mean;
        self.m2 += delta * delta_after;
        self.min = self.min.min(value);
        self.max = self.max.max(value);
    }

    const fn variance(self) -> f64 {
        if self.count == 0 {
            0.0
        } else {
            // Round-off can leave a mathematically non-negative second
            // moment a few ulps below zero after a long replay.
            let variance = self.m2 / self.count as f64;
            if variance < 0.0 { 0.0 } else { variance }
        }
    }
}

/// One sampled transition in an episode.  `return_value` is filled after the
/// episode is complete and is the discounted suffix return beginning here.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct MonteCarloStep {
    pub index: u32,
    pub state: u16,
    pub requested_action: Action,
    pub actual_action: Action,
    pub next_state: u16,
    pub reward: f64,
    pub discount_weight: f64,
    pub discounted_contribution: f64,
    pub return_value: f64,
    pub boundary_collision: bool,
    pub slipped: bool,
}

/// A single complete (or safety-truncated) episode and the estimates it
/// contributed to.
#[derive(Debug, Clone, PartialEq)]
pub struct MonteCarloEpisode {
    pub index: u32,
    pub start_state: u16,
    pub start_action: Action,
    pub steps: Vec<MonteCarloStep>,
    /// Discounted return from the initial state--action pair.
    pub return_value: f64,
    /// Alias retained in the core API for callers that use RL notation.
    pub discounted_return: f64,
    pub undiscounted_return: f64,
    pub terminated: bool,
    pub truncated: bool,
    pub updates: Vec<MonteCarloVisitUpdate>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct MonteCarloVisitUpdate {
    pub state: u16,
    pub action: Action,
    pub return_value: f64,
    pub visit_strategy: MonteCarloVisitStrategy,
    pub first_visit: bool,
    pub sample_count: u32,
    pub q_value: f64,
    pub variance: f64,
    pub policy_before: u8,
    pub policy_after: u8,
}

